mapper.select:
select t.template_name,t.template_name templateName,t.event_way,t.event_way
eventWay,t.remark,t.status_cd,t.status_cd statusCd,t.template_id,t.template_id
templateId,t.community_id,t.community_id communityId
from event_template t
where 1 =1

    and t.template_name= #{templateName}


    and t.event_way= #{eventWay}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.template_id= #{templateId}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

